#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    int a[10];
    for(int i = 0; i < 10; i++) cin >> a[i];

    vector<vector<int>> adj(n+1), radj(n+1);
    vector<unordered_set<int>> adj_set(n+1);

    for(int i = 0; i < m; i++){
        int u, v; cin >> u >> v;
        adj[u].push_back(v);
        radj[v].push_back(u);
        adj_set[u].insert(v);
    }

    auto has_edge = [&](int u, int v) -> bool {
        return adj_set[u].count(v);
    };

    auto now_f = chrono::steady_clock::now;
    auto start_time = now_f();
    auto elapsed_ms = [&](){return chrono::duration_cast<chrono::milliseconds>(now_f()-start_time).count();};

    // DAG check
    {
        vector<int> indeg(n+1, 0);
        for(int u = 1; u <= n; u++) for(int v : adj[u]) indeg[v]++;
        queue<int> q;
        for(int u = 1; u <= n; u++) if(indeg[u] == 0) q.push(u);
        vector<int> topo;
        topo.reserve(n);
        while(!q.empty()){
            int u = q.front(); q.pop(); topo.push_back(u);
            for(int v : adj[u]) if(--indeg[v] == 0) q.push(v);
        }
        if((int)topo.size() == n){
            vector<int> dp(n+1, 1), nxt(n+1, -1);
            for(int i = n-1; i >= 0; i--){
                int u = topo[i]; dp[u] = 1; nxt[u] = -1;
                for(int v : adj[u]){
                    if(dp[v] + 1 > dp[u]){
                        dp[u] = dp[v] + 1;
                        nxt[u] = v;
                    }
                }
            }
            int bs = topo[0];
            for(int u : topo) if(dp[u] > dp[bs]) bs = u;
            vector<int> path;
            for(int u = bs; u != -1; u = nxt[u]) path.push_back(u);
            cout << path.size() << "\n";
            for(int i = 0; i < (int)path.size(); i++){
                if(i) cout << ' ';
                cout << path[i];
            }
            cout << "\n";
            return 0;
        }
    }

    mt19937 rng(42);
    vector<int> best_path;

    // Warnsdorff-style greedy with randomization
    auto build_path = [&](int sv, vector<int>& path, vector<bool>& used) {
        path.clear();
        fill(used.begin(), used.end(), false);
        path.push_back(sv);
        used[sv] = true;

        // Extend back
        while(true){
            int c = path.back();
            int best = -1, best_score = INT_MAX;
            int cnt = 0;
            for(int v : adj[c]){
                if(used[v]) continue;
                int s = 0;
                for(int w : adj[v]) if(!used[w]) s++;
                if(s < best_score || (s == best_score && (rng() % (++cnt) == 0))){
                    if(s < best_score) cnt = 1;
                    best_score = s;
                    best = v;
                }
            }
            if(best == -1) break;
            used[best] = true;
            path.push_back(best);
        }

        // Extend front
        while(true){
            int c = path[0];
            int best = -1, best_score = INT_MAX;
            int cnt = 0;
            for(int v : radj[c]){
                if(used[v]) continue;
                int s = 0;
                for(int w : radj[v]) if(!used[w]) s++;
                if(s < best_score || (s == best_score && (rng() % (++cnt) == 0))){
                    if(s < best_score) cnt = 1;
                    best_score = s;
                    best = v;
                }
            }
            if(best == -1) break;
            used[best] = true;
            path.insert(path.begin(), best);
        }
    };

    // Rotation extension: if back is stuck, find neighbor in path, reverse suffix
    auto rotate_extend = [&](vector<int>& path, vector<bool>& used) -> bool {
        bool improved = false;
        bool changed = true;
        while(changed){
            changed = false;
            // Try rotation at back
            int tail = path.back();
            vector<int> cands;
            for(int v : adj[tail]){
                if(!used[v]) continue;
                // find position
                cands.push_back(v);
            }
            // Find positions
            unordered_map<int,int> posmap;
            for(int i = 0; i < (int)path.size(); i++) posmap[path[i]] = i;

            for(int v : cands){
                int p = posmap[v];
                if(p + 1 < (int)path.size()){
                    int nxt = path[p+1];
                    // Check if we can reverse p+1..end
                    // After reverse: path[0..p], tail, ..., path[p+1]
                    // We need edge tail -> path[end-1]? No, we need:
                    // path[p] -> tail (which is path[end]) exists? We have tail -> v = path[p]
                    // Actually we need path[p]->tail? No.
                    // We reverse segment [p+1..end]. New tail = path[p+1].
                    // Check: edge from tail to path[end-1]? i.e., path reversed would be
                    // path[0..p], path[end], path[end-1], ..., path[p+1]
                    // Need edge path[p] -> path[end] = tail -> but path[p] is not tail...
                    // We need has_edge(tail, path[(int)path.size()-2]) ... no.
                    // Rotation: reverse [p+1, end], need edges going backward
                    // This only works for undirected. For directed, skip.
                    (void)nxt;
                }
            }

            // Simple: try to find unvisited v with edge from tail, add
            {
                int c = path.back();
                for(int v : adj[c]){
                    if(!used[v]){
                        used[v] = true;
                        path.push_back(v);
                        changed = true;
                        improved = true;
                        break;
                    }
                }
            }
        }
        return improved;
    };

    vector<bool> used(n+1, false);
    vector<int> path;

    while(elapsed_ms() < 3800 && (int)best_path.size() < n){
        int sv = rng() % n + 1;
        build_path(sv, path, used);
        rotate_extend(path, used);

        // Vertex insertion
        for(int v = 1; v <= n && (int)path.size() < n; v++){
            if(used[v]) continue;
            for(int i = 0; i + 1 < (int)path.size(); i++){
                if(has_edge(path[i], v) && has_edge(v, path[i+1])){
                    path.insert(path.begin()+i+1, v);
                    used[v] = true;
                    break;
                }
            }
        }

        if((int)path.size() > (int)best_path.size()) best_path = path;
    }

    cout << best_path.size() << "\n";
    for(int i = 0; i < (int)best_path.size(); i++){
        if(i) cout << ' ';
        cout << best_path[i];
    }
    cout << "\n";
    return 0;
}
